#include <stdio.h>
#include <stdlib.h>

#define MAXV 8
#define MAXE 8

int main(int argc, char **argv) {
    if (argc < 3) {
        puts("INVALID_INPUT");
        return 1;
    }
    char *endptr;
    long n = strtol(argv[1], &endptr, 10);
    if (*endptr != '\0' || n < 0 || n >= MAXV) {
        puts("INVALID_INPUT");
        return 1;
    }
    long m = strtol(argv[2], &endptr, 10);
    if (*endptr != '\0' || m < 0 || m >= MAXE) {
        puts("INVALID_INPUT");
        return 1;
    }
    if (argc != 3 + 2 * m) {
        puts("INVALID_INPUT");
        return 1;
    }
    int adj[MAXV][MAXV] = {0};
    int indeg[MAXV] = {0};
    int done[MAXV] = {0};
    for (long i = 0; i < m; ++i) {
        long u = strtol(argv[3 + 2 * i], &endptr, 10);
        if (*endptr != '\0' || u < 0 || u >= n) {
            puts("INVALID_INPUT");
            return 1;
        }
        long v = strtol(argv[3 + 2 * i + 1], &endptr, 10);
        if (*endptr != '\0' || v < 0 || v >= n) {
            puts("INVALID_INPUT");
            return 1;
        }
        adj[u][v] = 1;
        indeg[v]++;
    }
    int printed = 0;
    while (printed < n) {
        int found = 0;
        for (int v = 0; v < n; ++v) {
            if (!done[v] && indeg[v] == 0) {
                printf("%d", v);
                putchar(' ');
                done[v] = 1;
                printed++;
                for (int w = 0; w < n; ++w) {
                    if (adj[v][w]) indeg[w]--;
                }
                found = 1;
                break;
            }
        }
        if (!found) {
            puts("CYCLE");
            return 1;
        }
    }
    putchar('\n');
    return 0;
}
